Certainly! Below is an example of **Breadth-First Search (BFS)** traversal in C++ for a graph using an adjacency list. We'll use the C++ Standard Template Library (STL) classes like `vector` and `queue` for implementation.

### BFS in C++

```cpp
#include <iostream>
#include <vector>
#include <queue>

using namespace std;

// Function to add an edge to the graph
void addEdge(vector<int> adj[], int u, int v) {
    adj[u].push_back(v);
    adj[v].push_back(u); // For undirected graph; remove this for directed
}

// BFS function
void BFS(vector<int> adj[], int V, int start) {
    vector<bool> visited(V, false);
    queue<int> q;

    visited[start] = true;
    q.push(start);

    while (!q.empty()) {
        int node = q.front();
        q.pop();
        cout << node << " ";

        for (int neighbour : adj[node]) {
            if (!visited[neighbour]) {
                visited[neighbour] = true;
                q.push(neighbour);
            }
        }
    }
}

int main() {
    int V = 5; // Number of vertices
    vector<int> adj[V];

    // Example graph:
    /*
      0
     / \
    1   2
    |   |
    3---4
    */

    addEdge(adj, 0, 1);
    addEdge(adj, 0, 2);
    addEdge(adj, 1, 3);
    addEdge(adj, 2, 4);
    addEdge(adj, 3, 4);

    cout << "BFS starting from vertex 0: ";
    BFS(adj, V, 0);

    return 0;
}
```

---

**Output:**
```
BFS starting from vertex 0: 0 1 2 3 4
```

---

### **How this works:**

- We use a `queue` to process vertices in FIFO order.
- `visited[]` array prevents revisiting nodes.
- Modify the `addEdge` function according to a directed or undirected graph.

