Certainly! Here’s a simple implementation of a **prefix sum array** in JavaScript, along with a function to return the sum of elements from index `l` to `r` **(inclusive)**.

---

```javascript
// Compute Prefix Sum Array
function computePrefixSum(arr) {
    let prefixSum = [];
    prefixSum[0] = arr[0];
    for(let i=1; i<arr.length; i++) {
        prefixSum[i] = prefixSum[i-1] + arr[i];
    }
    return prefixSum;
}

// Function to get sum from index l to r (inclusive)
function rangeSum(prefixSum, l, r) {
    if(l === 0) {
        return prefixSum[r];
    } else {
        return prefixSum[r] - prefixSum[l-1];
    }
}

// Example:
let arr = [2, 4, 5, 7, 8];
let prefixSum = computePrefixSum(arr);
console.log(prefixSum); // [2, 6, 11, 18, 26]

console.log( rangeSum(prefixSum, 1, 3) ); // 4 + 5 + 7 = 16
console.log( rangeSum(prefixSum, 0, 4) ); // 2 + 4 + 5 + 7 + 8 = 26
console.log( rangeSum(prefixSum, 2, 2) ); // 5
```

---

**How it works:**

- `computePrefixSum(arr)` returns an array where each element at `i` is `arr[0] + arr[1] + ... + arr[i]`.
- `rangeSum(prefixSum, l, r)` returns the sum of elements from `l` to `r` in `arr`.
  - If `l == 0`, just return `prefixSum[r]`.
  - Otherwise, return `prefixSum[r] - prefixSum[l-1]`.

