function squareOfOddSum(integers) {
    // Filter out odd numbers, sum them
    const oddSum = integers
        .filter(num => num % 2 !== 0)
        .reduce((sum, num) => sum + num, 0);
    // Square the sum
    const result = oddSum * oddSum;
    console.log(result);
}

// Example usage:
