Below is a simple Trie implementation in C++ using `std::vector` to store child nodes. This is especially useful if you want to store possibly more than just lowercase English letters, and want dynamic size at each node.

---

## Trie Implementation

```cpp
#include <iostream>
#include <vector>
#include <string>

struct TrieNode {
    bool isEnd;
    std::vector<std::pair<char, TrieNode*>> children;

    TrieNode() : isEnd(false) {}

    // Find or create a child node for given character
    TrieNode* getOrCreateChild(char ch) {
        for (auto& p : children) {
            if (p.first == ch)
                return p.second;
        }
        // Not found, create new node
        TrieNode* newNode = new TrieNode();
        children.push_back({ch, newNode});
        return newNode;
    }

    // Find the child node for given character
    TrieNode* getChild(char ch) {
        for (auto& p : children) {
            if (p.first == ch)
                return p.second;
        }
        return nullptr;
    }
};

class Trie {
public:
    Trie() {
        root = new TrieNode();
    }

    ~Trie() { freeNode(root); }

    // Insert word into the trie
    void insert(const std::string& word) {
        TrieNode* node = root;
        for(char ch : word) {
            node = node->getOrCreateChild(ch);
        }
        node->isEnd = true;
    }

    // Search for a word in the trie
    bool search(const std::string& word) {
        TrieNode* node = root;
        for(char ch : word) {
            node = node->getChild(ch);
            if (!node) return false;
        }
        return node->isEnd;
    }

    // Check if any word in the trie starts with prefix
    bool startsWith(const std::string& prefix) {
        TrieNode* node = root;
        for(char ch : prefix) {
            node = node->getChild(ch);
            if (!node) return false;
        }
        return true;
    }

private:
    TrieNode* root;

    void freeNode(TrieNode* node) {
        if (!node) return;
        for (auto& p : node->children) {
            freeNode(p.second);
        }
        delete node;
    }
};

int main() {
    Trie trie;

    trie.insert("apple");
    std::cout << std::boolalpha;
    std::cout << trie.search("apple") << std::endl;   // true
    std::cout << trie.search("app") << std::endl;     // false
    std::cout << trie.startsWith("app") << std::endl; // true
    trie.insert("app");
    std::cout << trie.search("app") << std::endl;     // true
    return 0;
}
```

---

### Notes

- Child nodes are stored as `std::vector<std::pair<char, TrieNode*>>`.
- Insertion (`insert`) and search (`search`, `startsWith`) are O(k * n) where n is the word/prefix length and k is the average number of children, since std::vector is used for lookup (not as efficient as array/hash).
- This implementation allows for arbitrary character sets in your Trie.
- For performance-critical uses with fixed alphabets, prefer an array for children instead.

