Given a linked list:  
`1 -> 2 -> 3 -> 4 -> 5 -> 6 -> 7 -> 8 -> NULL`

**Task:** Rearrange so that all odd numbers appear first, followed by all even numbers.  
**Output:**  
`1 -> 3 -> 5 -> 7 -> 2 -> 4 -> 6 -> 8 -> NULL`

---

## **Approach**

1. Maintain two pointers (lists): one for odds, one for evens.
2. Traverse the original list and separate nodes into odd/even lists.
3. After traversal, connect the odd list to the even list.
4. Set the end of the final list to `NULL`.

---

## **Algorithm (Pseudocode or C-like):**

```c
struct Node* rearrangeEvenOdd(struct Node* head) {
    struct Node *oddStart = NULL, *oddEnd = NULL;
    struct Node *evenStart = NULL, *evenEnd = NULL;
    struct Node* curr = head;

    while (curr != NULL) {
        int val = curr->data;
        if (val % 2 == 1) {  // Odd node
            if (!oddStart) {
                oddStart = oddEnd = curr;
            } else {
                oddEnd->next = curr;
                oddEnd = oddEnd->next;
            }
        } else {  // Even node
            if (!evenStart) {
                evenStart = evenEnd = curr;
            } else {
                evenEnd->next = curr;
                evenEnd = evenEnd->next;
            }
        }
        curr = curr->next;
    }

    // If there are no odd or no even nodes
    if (!oddStart || !evenStart)
        return head;

    // Combine odd and even
    oddEnd->next = evenStart;
    evenEnd->next = NULL;

    return oddStart;
}
```

---

## **Python Implementation**

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def rearrange_even_after_odd(head):
    if not head:
        return head

    odd_start = odd_end = None
    even_start = even_end = None
    curr = head

    while curr:
        if curr.data % 2 == 1:  # Odd
            if not odd_start:
                odd_start = odd_end = curr
            else:
                odd_end.next = curr
                odd_end = odd_end.next
        else:  # Even
            if not even_start:
                even_start = even_end = curr
            else:
                even_end.next = curr
                even_end = even_end.next
        curr = curr.next

    # If there are no odd or no even nodes
    if not odd_start or not even_start:
        return head

    # Connect odd list to even list
    odd_end.next = even_start
    even_end.next = None

    return odd_start

# Helper to print linked list
def print_list(head):
    while head:
        print(head.data, end="->" if head.next else "")
        head = head.next
    print()

# Example usage:
# 1->2->3->4->5->6->7->8->NULL
nodes = [Node(i) for i in range(1, 9)]
for i in range(7):
    nodes[i].next = nodes[i+1]
head = nodes[0]

head = rearrange_even_after_odd(head)
print_list(head)  # Output: 1->3->5->7->2->4->6->8
```

---

## **Explanation**

- The list is split into two: all odd nodes and all even nodes.
- Then you join both, odds first, then evens.
- Time Complexity: **O(n)** (one traversal)
- Space Complexity: **O(1)** (in-place links, no extra nodes created)

