Here's a multithreaded `FizzBuzz` implementation in **Python**, using `threading` and a `Lock` as a mutex to synchronize printing. Each thread is responsible for one type of output (fizz, buzz, fizzbuzz, number).

---

```python
import threading

class FizzBuzz:
    def __init__(self, n):
        self.n = n
        self.current = 1
        self.lock = threading.Lock()

    def fizz(self):
        while True:
            with self.lock:
                if self.current > self.n:
                    return
                if self.current % 3 == 0 and self.current % 5 != 0:
                    print("fizz")
                    self.current += 1

    def buzz(self):
        while True:
            with self.lock:
                if self.current > self.n:
                    return
                if self.current % 5 == 0 and self.current % 3 != 0:
                    print("buzz")
                    self.current += 1

    def fizzbuzz(self):
        while True:
            with self.lock:
                if self.current > self.n:
                    return
                if self.current % 15 == 0:
                    print("fizzbuzz")
                    self.current += 1

    def number(self):
        while True:
            with self.lock:
                if self.current > self.n:
                    return
                if self.current % 3 != 0 and self.current % 5 != 0:
                    print(self.current)
                    self.current += 1

def main():
    n = 20
    fb = FizzBuzz(n)
    threads = [
        threading.Thread(target=fb.fizz),
        threading.Thread(target=fb.buzz),
        threading.Thread(target=fb.fizzbuzz),
        threading.Thread(target=fb.number)
    ]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

if __name__ == "__main__":
    main()
```

---

**Key points:**
- Each method (`fizz`, `buzz`, `fizzbuzz`, `number`) is supposed to print when its condition is met.
- The `self.lock` ensures only one thread prints & increments at a time.
- The threads exit if the current number exceeds `n`.

