Certainly! Below is a simple multi-threaded C++ application for finding prime numbers up to a specified limit using multiple threads. This program:

- Uses `<thread>` from the C++11 standard library.
- Each thread processes a subrange of numbers and writes its primes into a shared vector, protected by a mutex.
- The program is easy to modify for the number of threads and the upper bound for prime search.

---

```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <cmath>

// Function to check if a number is prime
bool is_prime(int n) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    int limit = static_cast<int>(std::sqrt(n));
    for (int i = 3; i <= limit; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

// Function for each thread to find primes in a subrange
void find_primes(int start, int end, std::vector<int>& primes, std::mutex& primes_mutex) {
    for (int i = start; i <= end; i++) {
        if (is_prime(i)) {
            std::lock_guard<std::mutex> lock(primes_mutex);
            primes.push_back(i);
        }
    }
}

int main() {
    const int upper_limit = 100000; // Find primes up to this number
    const int num_threads = std::thread::hardware_concurrency(); // Adjust based on your CPU
    std::vector<std::thread> threads;
    std::vector<int> primes;
    std::mutex primes_mutex;

    int numbers_per_thread = upper_limit / num_threads;
    int start = 2;

    // Launch threads
    for (int i = 0; i < num_threads; ++i) {
        int end = (i == num_threads - 1) ? upper_limit : start + numbers_per_thread - 1;
        threads.emplace_back(find_primes, start, end, std::ref(primes), std::ref(primes_mutex));
        start = end + 1;
    }

    // Wait for threads to finish
    for (auto& th : threads) {
        th.join();
    }

    // Optional: Sort primes since pushing order is not guaranteed
    std::sort(primes.begin(), primes.end());

    // Print some results
    std::cout << "Number of primes found: " << primes.size() << std::endl;
    std::cout << "First 10 primes: ";
    for (size_t i = 0; i < std::min<size_t>(10, primes.size()); ++i)
        std::cout << primes[i] << " ";
    std::cout << std::endl;

    return 0;
}
```

#### How it works:

- Set `upper_limit` to change the highest number to check.
- The program will use as many hardware threads as available (change `num_threads` if you want fewer threads).
- Results are stored in a vector protected by a mutex.
- At the end, it prints the number of primes found and the first 10 primes.

#### How to compile:

```sh
g++ -std=c++11 -pthread -O2 primes_mt.cpp -o primes_mt
```

#### Note:
If you want even better performance, consider optimizations like using segmented sieves for larger limits. This example is straightforward and demonstrates multi-threading with mutex-protected shared resources.

