<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Moving Ball Animation</title>
  <style>
    body, html {
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #20232a;
    }
    #container {
      position: absolute;
      width: 100vw;
      height: 100vh;
      top: 0;
      left: 0;
    }
    #ball {
      position: absolute;
      width: 60px;
      height: 60px;
      border-radius: 50%;
      background: #61dafb;
      box-shadow: 0 8px 24px #1b2836aa;
      top: 50%;
      transform: translateY(-50%);
      left: 0;
    }
  </style>
</head>
<body>
  <div id="container">
    <div id="ball"></div>
  </div>
  <script>
    const ball = document.getElementById('ball');
    const ballDiameter = 60; // px

    // Animation states
    let direction = 1; // 1 = right, -1 = left
    let position = 0; // current left in px
    let speed = 3; // px per frame

    // On resize, recalculate the bounds
    function getMaxX() {
      return window.innerWidth - ballDiameter;
    }

    function animate() {
      // Update position
      position += speed * direction;

      // Reverse direction at bounds
      if (position >= getMaxX()) {
        position = getMaxX();
        direction = -1;
      } else if (position <= 0) {
        position = 0;
        direction = 1;
      }

      // Apply new position
      ball.style.left = position + 'px';

      requestAnimationFrame(animate);
    }

    // Start position: horizontally centered
    position = 0;
    ball.style.left = '0px';

    // Adjust position if the window is resized
    window.addEventListener('resize', function() {
      // If ball is out of bounds, put it back in
      if (position > getMaxX()) {
        position = getMaxX();
      }
      ball.style.left = position + 'px';
    });

    animate();
  </script>
</body>
</html>
```

**What this does:**

- The ball starts at the left side, travels smoothly to the right edge, reverses direction, and comes back, repeating forever.
- The ball stays vertically centered.
- Responsive: Handles window resizing.
- Easily customizable (change size, speed, color, etc.)

