Certainly! Below is a C++ function that takes a `std::vector<int>` as its parameter and returns a `std::vector<int>` containing **the longest (contiguous) increasing sequence** found in the input vector.

If you need the **longest strictly increasing contiguous subsequence** (i.e., each next element is greater than the previous), that's the most common interpretation.

```cpp
#include <vector>

std::vector<int> longestIncreasingSequence(const std::vector<int>& nums) {
    if (nums.empty()) return {};
    int maxStart = 0, maxLen = 1;
    int currStart = 0, currLen = 1;

    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] > nums[i-1]) {
            ++currLen;
        } else {
            if (currLen > maxLen) {
                maxLen = currLen;
                maxStart = currStart;
            }
            currStart = i;
            currLen = 1;
        }
    }
    // Check last sequence
    if (currLen > maxLen) {
        maxLen = currLen;
        maxStart = currStart;
    }
    return std::vector<int>(nums.begin() + maxStart, nums.begin() + maxStart + maxLen);
}
```

### Usage Example

```cpp
#include <iostream>

int main() {
    std::vector<int> v = {1, 2, 3, 2, 3, 4, 5, 1, 2};
    auto seq = longestIncreasingSequence(v);
    for (int x : seq) std::cout << x << " ";
    // Output: 2 3 4 5
}
```

