public class ProgressBarExample {
    public static void main(String[] args) {
        int[] arr = new int[100];
        for (int i = 0; i < arr.length; i++) arr[i] = i;

        showProgress(arr);
    }

    public static void showProgress(int[] arr) {
        int total = arr.length;
        int barLength = 50; // Length of the progress bar

        for (int i = 0; i < arr.length; i++) {
            // Simulate some work
            try { Thread.sleep(20); } catch (InterruptedException e) {}

            // Calculate progress
            double progress = (double)(i + 1) / total;
            int filledLength = (int) (progress * barLength);
            String bar = "=".repeat(filledLength) + " ".repeat(barLength - filledLength);

            // Output progress bar
            System.out.printf("\r[%s] %d%%", bar, (int)(progress * 100));
            System.out.flush();
        }
        System.out.println("\nDone!");
    }
}
```

### Notes:

- The `\r` carriage return makes the progress bar stay on one line.
